def is_multiply_prime(a):
    if a < 8:
        return False
    primes = []
    for num in range(2, 100):
        is_prime = True
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    for p in primes:
        for q in primes:
            for r in primes:
                if p * q * r == a:
                    return True
    return False
